// Helper function for RTL-aware positioning
export const getRTLStyle = (
  ltrStyle: ViewStyle | TextStyle, 
  rtlStyle: ViewStyle | TextStyle
): ViewStyle | TextStyle => {
  return isRTL() ? rtlStyle : ltrStyle;
};

