import AsyncStorage from '@react-native-async-storage/async-storage';
import { traceEvent, getTimeline } from './deepTracer';
import { getSessionSnapshots } from './sessionDebugger';

interface SupabaseRequest {
  timestamp: string;
  endpoint: string;
  payload?: any;
  response?: any;
  error?: any;
  latencyMs?: number;
  status?: string;
}

interface AppStateChange {
  timestamp: string;
  from: string;
  to: string;
}

interface LogReport {
  generatedAt: string;
  appStateTimeline: AppStateChange[];
  sessionSnapshots: any[];
  supabaseRequests: SupabaseRequest[];
  fullTimeline: any[];
  lastError?: any;
}

class LogCollector {
  private requests: SupabaseRequest[] = [];
  private appStateChanges: AppStateChange[] = [];
  private readonly MAX_REQUESTS = 20;
  private readonly MAX_STATE_CHANGES = 30;
  private readonly STORAGE_KEY = '@log_collector_data';

  logRequest(endpoint: string, data: Partial<SupabaseRequest>) {
    const request: SupabaseRequest = {
      timestamp: new Date().toISOString(),
      endpoint,
      ...data,
    };

    this.requests.push(request);

    if (this.requests.length > this.MAX_REQUESTS) {
      this.requests.shift();
    }

    traceEvent('SUPABASE_REQUEST', endpoint, {
      latency: data.latencyMs,
      status: data.status,
      hasError: !!data.error,
    });

    this.saveToStorage();
  }

  logAppStateChange(from: string, to: string) {
    const change: AppStateChange = {
      timestamp: new Date().toISOString(),
      from,
      to,
    };

    this.appStateChanges.push(change);

    if (this.appStateChanges.length > this.MAX_STATE_CHANGES) {
      this.appStateChanges.shift();
    }

    traceEvent('APP_STATE', `${from} -> ${to}`, { timestamp: change.timestamp });

    this.saveToStorage();
  }

  async generateReport(): Promise<LogReport> {
    const report: LogReport = {
      generatedAt: new Date().toISOString(),
      appStateTimeline: [...this.appStateChanges],
      sessionSnapshots: getSessionSnapshots(),
      supabaseRequests: [...this.requests],
      fullTimeline: getTimeline(),
    };

    const lastRequest = this.requests[this.requests.length - 1];
    if (lastRequest?.error) {
      report.lastError = lastRequest.error;
    }

    return report;
  }

  async saveReport() {
    const report = await this.generateReport();
    const key = `@log_report_${Date.now()}`;

    try {
      await AsyncStorage.setItem(key, JSON.stringify(report, null, 2));
      console.log('📊 Log report saved to:', key);
      return key;
    } catch (error) {
      console.error('Failed to save log report:', error);
    }
  }

  async printReport() {
    const report = await this.generateReport();

    console.log('\n========== LOG REPORT ==========');
    console.log('Generated at:', report.generatedAt);

    console.log('\n--- App State Timeline ---');
    report.appStateTimeline.forEach((change, idx) => {
      const time = new Date(change.timestamp).toLocaleTimeString();
      console.log(`${idx + 1}. [${time}] ${change.from} -> ${change.to}`);
    });

    console.log('\n--- Recent Supabase Requests ---');
    report.supabaseRequests.forEach((req, idx) => {
      const time = new Date(req.timestamp).toLocaleTimeString();
      console.log(`${idx + 1}. [${time}] ${req.endpoint}`);
      console.log(`   Status: ${req.status || 'unknown'}, Latency: ${req.latencyMs || 'N/A'}ms`);
      if (req.error) {
        console.log(`   Error:`, req.error);
      }
    });

    if (report.lastError) {
      console.log('\n--- Last Error ---');
      console.log(JSON.stringify(report.lastError, null, 2));
    }

    console.log('\n================================\n');
  }

  private async saveToStorage() {
    try {
      const data = {
        requests: this.requests,
        appStateChanges: this.appStateChanges,
      };
      await AsyncStorage.setItem(this.STORAGE_KEY, JSON.stringify(data));
    } catch (error) {
      console.error('Failed to save log collector data:', error);
    }
  }

  async loadFromStorage() {
    try {
      const stored = await AsyncStorage.getItem(this.STORAGE_KEY);
      if (stored) {
        const data = JSON.parse(stored);
        this.requests = data.requests || [];
        this.appStateChanges = data.appStateChanges || [];
      }
    } catch (error) {
      console.error('Failed to load log collector data:', error);
    }
  }

  async clearAll() {
    this.requests = [];
    this.appStateChanges = [];
    try {
      await AsyncStorage.removeItem(this.STORAGE_KEY);
    } catch (error) {
      console.error('Failed to clear log collector data:', error);
    }
  }
}

const collector = new LogCollector();

export const logSupabaseRequest = (endpoint: string, data: Partial<SupabaseRequest>) =>
  collector.logRequest(endpoint, data);

export const logAppStateChange = (from: string, to: string) =>
  collector.logAppStateChange(from, to);

export const generateLogReport = () => collector.generateReport();
export const saveLogReport = () => collector.saveReport();
export const printLogReport = () => collector.printReport();
export const loadLogCollector = () => collector.loadFromStorage();
export const clearLogCollector = () => collector.clearAll();

if (typeof window !== 'undefined') {
  (window as any).printLogReport = printLogReport;
  (window as any).saveLogReport = saveLogReport;
  (window as any).generateLogReport = generateLogReport;
}

utils/persistentWriteQueue.ts.content:
import AsyncStorage from '@react-native-async-storage/async-storage';
import { getDeviceId } from './clientUuid';

export interface PersistentWriteItem<T = any> {
  localId: string;
  deviceId: string;
  userId?: string;
  type: 'medication' | 'symptom' | 'lab_report' | 'other';
  payload: T;
  createdAt: number;
  attempts: number;
  lastAttempt?: number;
  status: 'pending' | 'processing' | 'synced' | 'failed';
  serverId?: string;
  error?: string;
}

const QUEUE_STORAGE_KEY = 'hamlymd_write_queue';
const MAX_ATTEMPTS = 5;
const BACKOFF_BASE_MS = 500;

class PersistentWriteQueue {
  private queue: Map<string, PersistentWriteItem> = new Map();
  private processing = false;
  private listeners: Set<(queue: PersistentWriteItem[]) => void> = new Set();

  async initialize(): Promise<void> {
    await this.loadFromStorage();
    console.log(`📝 Write queue initialized with ${this.queue.size} pending items`);
  }

  private async loadFromStorage(): Promise<void> {
    try {
      const stored = await AsyncStorage.getItem(QUEUE_STORAGE_KEY);
      if (stored) {
        const items: PersistentWriteItem[] = JSON.parse(stored);
        items.forEach(item => {
          this.queue.set(item.localId, item);
        });
      }
    } catch (error) {
      console.error('Failed to load write queue from storage:', error);
    }
  }

  private async saveToStorage(): Promise<void> {
    try {
      const items = Array.from(this.queue.values());
      await AsyncStorage.setItem(QUEUE_STORAGE_KEY, JSON.stringify(items));
    } catch (error) {
      console.error('Failed to save write queue to storage:', error);
    }
  }

  private notifyListeners(): void {
    const items = this.getAllItems();
    this.listeners.forEach(listener => {
      try {
        listener(items);
      } catch (error) {
        console.error('Error in queue listener:', error);
      }
    });
  }

  subscribe(listener: (queue: PersistentWriteItem[]) => void): () => void {
    this.listeners.add(listener);
    listener(this.getAllItems());

    return () => {
      this.listeners.delete(listener);
    };
  }

  async enqueue<T>(
    type: PersistentWriteItem['type'],
    payload: T,
    userId?: string
  ): Promise<string> {
    const deviceId = await getDeviceId();
    const localId = `${deviceId}_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

    const item: PersistentWriteItem<T> = {
      localId,
      deviceId,
      userId,
      type,
      payload,
      createdAt: Date.now(),
      attempts: 0,
      status: 'pending',
    };

    this.queue.set(localId, item);
    await this.saveToStorage();
    this.notifyListeners();

    console.log(`📝 Enqueued write: ${type} (${localId})`);

    this.processQueue().catch(err =>
      console.error('Error processing queue after enqueue:', err)
    );

    return localId;
  }

  async processQueue(
    executor?: (item: PersistentWriteItem) => Promise<{ serverId?: string; error?: string }>
  ): Promise<void> {
    if (this.processing) {
      console.log('Queue already processing, skipping');
      return;
    }

    this.processing = true;

    try {
      const pendingItems = Array.from(this.queue.values()).filter(
        item => item.status === 'pending' || item.status === 'failed'
      );

      if (pendingItems.length === 0) {
        return;
      }

      console.log(`🔄 Processing ${pendingItems.length} pending write(s)`);

      for (const item of pendingItems) {
        if (item.attempts >= MAX_ATTEMPTS) {
          console.error(`❌ Item ${item.localId} exhausted all attempts, marking as failed`);
          item.status = 'failed';
          item.error = 'Max attempts reached';
          await this.saveToStorage();
          this.notifyListeners();
          continue;
        }

        const backoffDelay = BACKOFF_BASE_MS * Math.pow(2, item.attempts);
        const timeSinceLastAttempt = Date.now() - (item.lastAttempt || 0);

        if (item.lastAttempt && timeSinceLastAttempt < backoffDelay) {
          continue;
        }

        item.status = 'processing';
        item.attempts++;
        item.lastAttempt = Date.now();
        this.notifyListeners();

        if (executor) {
          try {
            const result = await executor(item);

            if (result.serverId) {
              item.serverId = result.serverId;
              item.status = 'synced';
              item.error = undefined;
              console.log(`✅ Synced ${item.type}: ${item.localId} → ${result.serverId}`);
            } else if (result.error) {
              item.status = 'failed';
              item.error = result.error;
              console.error(`❌ Failed to sync ${item.localId}:`, result.error);
            }
          } catch (error) {
            item.status = 'failed';
            item.error = error instanceof Error ? error.message : String(error);
            console.error(`❌ Error syncing ${item.localId}:`, error);
          }

          await this.saveToStorage();
          this.notifyListeners();
        }
      }
    } finally {
      this.processing = false;
    }
  }

  getItem(localId: string): PersistentWriteItem | undefined {
    return this.queue.get(localId);
  }

  getAllItems(): PersistentWriteItem[] {
    return Array.from(this.queue.values());
  }

  getPendingItems(): PersistentWriteItem[] {
    return this.getAllItems().filter(item => item.status === 'pending' || item.status === 'processing');
  }

  async markSynced(localId: string, serverId: string): Promise<void> {
    const item = this.queue.get(localId);
    if (item) {
      item.status = 'synced';
      item.serverId = serverId;
      item.error = undefined;
      await this.saveToStorage();
      this.notifyListeners();
      console.log(`✅ Marked ${localId} as synced with server ID ${serverId}`);
    }
  }

  async markFailed(localId: string, error: string): Promise<void> {
    const item = this.queue.get(localId);
    if (item) {
      item.status = 'failed';
      item.error = error;
      await this.saveToStorage();
      this.notifyListeners();
      console.error(`❌ Marked ${localId} as failed:`, error);
    }
  }

  async removeSynced(): Promise<void> {
    const beforeSize = this.queue.size;
    const syncedItems = Array.from(this.queue.values()).filter(item => item.status === 'synced');

    syncedItems.forEach(item => {
      this.queue.delete(item.localId);
    });

    if (syncedItems.length > 0) {
      await this.saveToStorage();
      this.notifyListeners();
      console.log(`🗑️ Removed ${syncedItems.length} synced items (${beforeSize} → ${this.queue.size})`);
    }
  }

  async clearAll(): Promise<void> {
    this.queue.clear();
    await AsyncStorage.removeItem(QUEUE_STORAGE_KEY);
    this.notifyListeners();
    console.log('🗑️ Cleared all write queue items');
  }

  getStatus() {
    const items = this.getAllItems();
    return {
      total: items.length,
      pending: items.filter(i => i.status === 'pending').length,
      processingItems: items.filter(i => i.status === 'processing').length,
      synced: items.filter(i => i.status === 'synced').length,
      failed: items.filter(i => i.status === 'failed').length,
      isProcessing: this.processing,
    };
  }
}

export const persistentWriteQueue = new PersistentWriteQueue();

if (typeof window !== 'undefined') {
  (window as any).writeQueueStatus = () => persistentWriteQueue.getStatus();
  (window as any).writeQueueClear = () => persistentWriteQueue.clearAll();
  (window as any).writeQueueItems = () => persistentWriteQueue.getAllItems();
}

app/(tabs)/lab-results/[reportId].tsx.content:
import React, { useState, useEffect, useRef } from "react";
import {
  View,
  Text,
  StyleSheet,
  ScrollView,
  SafeAreaView,
  ActivityIndicator,
  TouchableOpacity,
} from "react-native";
import { useLocalSearchParams, useRouter } from "expo-router";
import Icon from "react-native-vector-icons/MaterialIcons";
import { LabReport } from "@/types";
import { loadData, STORAGE_KEYS } from "@/utils/storage";
import LabResultCard from "@/components/LabResultCard";
import { t, isRTL } from "@/utils/i18n";
import { createShadowStyle } from "@/utils/shadowStyles";
import LocalizedHeader from "@/components/LocalizedHeader";
import { useIsRTL } from "@/utils/useIsRTL";
import ModernHeader from "@/components/ModernHeader";
import UltimateSafeView from "@/components/UltimateSafeView";
import { sessionManager } from "@/services/session/sessionManager";

// Helper function to format date, assuming it's needed for the subtitle
const formatDate = (dateString: string) => {
  if (!dateString) return "";
  try {
    const date = new Date(dateString);
    return date.toLocaleDateString(); // Adjust formatting as needed
  } catch (e) {
    console.error("Error formatting date:", e);
    return dateString; // Fallback to original string if parsing fails
  }
};

export default function LabReportDetailsScreen() {
  const { reportId } = useLocalSearchParams<{ reportId: string }>();
  const router = useRouter();
  const [report, setReport] = useState<LabReport | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const isRTLDirection = useIsRTL();
  const mountedRef = useRef(false);

  useEffect(() => {
    mountedRef.current = true;
    const loadId = `load_report_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`;
    console.log(`[${loadId}] 🔍 Starting loadReport for reportId:`, reportId);
    loadReport(loadId);

    return () => {
      mountedRef.current = false;
    };
  }, [reportId]);

  const loadReport = async (loadId: string) => {
    console.log(`[${loadId}] 📊 Setting loading=true`);
    setLoading(true);
    setError(null);

    try {
      // Ensure session is valid before proceeding
      console.log(`[${loadId}] 🔐 Ensuring session is valid...`);
      await sessionManager.ensureSession();

      // Wait for any in-progress resync to complete
      if (sessionManager.isResyncInProgress()) {
        console.log(`[${loadId}] ⏳ Resync in progress, waiting for completion...`);
        await sessionManager.waitForResync();
        console.log(`[${loadId}] ✅ Resync completed, continuing with fresh data`);
      }

      // Try to get from DataContext first (instant, no network call)
      const { labReports } = await import("@/contexts/DataContext").then(m => {
        const { useData } = m;
        // Access context if available
        try {
          return useData();
        } catch {
          return { labReports: [] };
        }
      });

      console.log(`[${loadId}] 🔍 Checking DataContext for report ${reportId}`);
      const cachedReport = labReports.find((r: any) => r.id === reportId);

      // Only use cached data if it exists and component is still mounted
      if (cachedReport && mountedRef.current) {
        console.log(`[${loadId}] ✅ Found report in DataContext, using cached version`);
        const formattedReport: LabReport = {
          id: cachedReport.id,
          date: cachedReport.date,
          summary: cachedReport.summary,
          source: cachedReport.source,
          labResults: cachedReport.labResults,
        };
        setReport(formattedReport);
        setLoading(false);
        return;
      }

      console.log(`[${loadId}] ⚠️ Report not in cache, loading from database...`);
      console.log(`[${loadId}] 📥 Importing getLabReportById`);
      const { getLabReportById } = await import("@/utils/supabaseStorage");

      // Direct query with retry logic - handle network issues
      console.log(`[${loadId}] 🔄 Loading report directly from database`);
      const startTime = Date.now();

      let supabaseReport = null;
      let lastError = null;

      // Retry up to 1 time with shorter timeout
      for (let attempt = 1; attempt <= 1; attempt++) {
        try {
          const timeout = 10000; // 10s timeout
          console.log(`[${loadId}] 🔄 Attempt ${attempt}/1 with ${timeout}ms timeout`);

          supabaseReport = await Promise.race([
            getLabReportById(reportId),
            new Promise<never>((_, reject) => 
              setTimeout(() => reject(new Error('Direct query timeout')), timeout)
            )
          ]);

          console.log(`[${loadId}] ✅ Report loaded on attempt ${attempt}`);
          break; // Success, exit loop
        } catch (err) {
          lastError = err;
          console.warn(`[${loadId}] ⚠️ Attempt ${attempt} failed:`, err instanceof Error ? err.message : String(err));
        }
      }

      if (!supabaseReport && lastError) {
        throw lastError;
      }

      const loadTime = Date.now() - startTime;

      console.log(`[${loadId}] ⏱️ Report loaded in ${loadTime}ms`, {
        hasReport: !!supabaseReport,
        reportId: supabaseReport?.id
      });

      if (supabaseReport && mountedRef.current) {
        console.log(`[${loadId}] 📋 Formatting report data...`, {
          id: supabaseReport.id,
          date: supabaseReport.date,
          source: supabaseReport.source,
          labResultsCount: supabaseReport.lab_results?.length || 0
        });

        const formattedReport: LabReport = {
          id: supabaseReport.id,
          date: supabaseReport.date,
          summary: supabaseReport.summary,
          source: supabaseReport.source,
          labResults: (supabaseReport.lab_results || []).map((result: any) => ({
            id: result.id,
            testName: result.test_name,
            value: result.value,
            unit: result.unit,
            referenceRange: result.reference_range,
            date: result.date,
            isAbnormal: result.is_abnormal,
            notes: result.notes || undefined,
            category: result.category,
            trimester: result.trimester,
            explanation: result.explanation || undefined,
          })),
        };

        console.log(`[${loadId}] 💾 Setting report state with ${formattedReport.labResults.length} lab results`);
        setReport(formattedReport);
        console.log(`[${loadId}] ✅ Report loaded successfully:`, formattedReport.id);
      } else if (!mountedRef.current) {
        console.log(`[${loadId}] 🚫 Component unmounted, skipping state update`);
      } else {
        console.log(`[${loadId}] ⚠️ No report found for reportId:`, reportId);
        setError(t("reportNotFound"));
      }
    } catch (error) {
      console.error(`[${loadId}] ❌ Error loading report:`, {
        error: error instanceof Error ? error.message : String(error),
        stack: error instanceof Error ? error.stack : undefined,
        reportId
      });

      // User-friendly error messages in Arabic
      if (error instanceof Error && error.message.includes('timeout')) {
        setError("فشل تحميل التقرير - يرجى التحقق من اتصالك بالإنترنت والمحاولة مرة أخرى");
      } else {
        setError("حدث خطأ في تحميل التقرير");
      }
    } finally {
      console.log(`[${loadId}] 🏁 Setting loading=false`);
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <SafeAreaView style={styles.container}>

        <LocalizedHeader
          title={t("labResults")}
          subtitle={t("loading")}
          showLogo={false}
          leading={
            <TouchableOpacity
              onPress={() => router.back()}
              style={styles.backButton}
            >

              <Icon name="arrow-back" size={24} color="#333" />
            </TouchableOpacity>
          }
        />
        <View style={styles.loadingContainer}>

          <ActivityIndicator size="large" color="#E91E63" />
          <Text style={styles.loadingText}>{t("loadingReport")}...</Text>
        </View>
      </SafeAreaView>
    );
  }

  if (error || !report) {
    return (
      <SafeAreaView style={styles.container}>

        <LocalizedHeader
          title={t("labResults")}
          subtitle={t("error")}
          showLogo={false}
          leading={
            <TouchableOpacity
              onPress={() => router.back()}
              style={styles.backButton}
            >

              <Icon name="arrow-back" size={24} color="#333" />
            </TouchableOpacity>
          }
        />
        <View style={styles.errorContainer}>

          <Icon name="description" size={64} color="#E0E0E0" />
          <Text style={styles.errorText}>{error || t("reportNotFound")}</Text>
          <TouchableOpacity
            onPress={() => router.back()}
            style={styles.backToListButton}
          >

            <Text style={styles.backToListText}>{t("backToReports")}</Text>
          </TouchableOpacity>
        </View>
      </SafeAreaView>
    );
  }

  const abnormalResults = report.labResults.filter(
    (result) => result.isAbnormal,
  );

  return (
    <SafeAreaView style={styles.container}>

      <ModernHeader
        title={report.summary || t("reportSummaryTitle")}
        subtitle={`${t("date")}: ${formatDate(report.date)}`}
        showBackButton={true}
        onBackPress={() => router.back()}
        variant="compact"
        elevation={true}
        backgroundColor="#FFFFFF"
        textColor="#1A1A1A"
      />
      <ScrollView style={styles.content} showsVerticalScrollIndicator={false}>

        <View style={styles.summaryCard}>

          <View style={styles.summaryHeader}>

            <Icon name="event" size={20} color="#E91E63" />
            <Text style={styles.summaryTitle}>
              {t("reportSummaryTitle")}
            </Text>
          </View>
          <Text style={styles.summaryText}>{report.summary}</Text>
          <View style={styles.summaryStats}>

            <View style={styles.summaryStatItem}>

              <Text style={styles.summaryStatValue}>
                {report.labResults.length}
              </Text>
              <Text style={styles.summaryStatLabel}>
                {t("totalTests")}
              </Text>
            </View>
            <View style={styles.summaryStatItem}>

              <Text
                style={[
                  styles.summaryStatValue,
                  abnormalResults.length > 0 && styles.abnormalStatValue,
                ]}
              >

                {abnormalResults.length}
              </Text>
              <Text style={styles.summaryStatLabel}>
                {t("abnormalResult")}
              </Text>
            </View>
            <View style={styles.summaryStatItem}>

              <Text style={styles.summaryStatValue}>

                {report.labResults.length - abnormalResults.length}
              </Text>
              <Text style={styles.summaryStatLabel}>
                {t("normalResult")}
              </Text>
            </View>
          </View>
          <View style={styles.sourceInfo}>

            <Text style={styles.sourceLabel}>{t("sourceLabel")}</Text>
            <Text
              style={[
                styles.sourceValue,
                {
                  color: report.source === "upload" ? "#4CAF50" : "#E91E63",
                },
              ]}
            >

              {report.source === "upload"
                ? t("uploadedDocument")
                : t("manualEntry")}
            </Text>
          </View>
        </View>
        <View style={styles.resultsSection}>

