import React, { useMemo } from "react";
import {
  Text,
  TouchableOpacity,
  StyleSheet,
  ViewStyle,
  TextStyle,
  ActivityIndicator,
  useWindowDimensions,
} from "react-native";
import {
  useLocalizedStyles,
  COLORS,
  SPACING,
  TYPOGRAPHY,
} from "@/utils/modernStyles";
import { createShadowStyle } from "@/utils/shadowStyles";
import { responsiveFontSize } from "@/utils/responsive";

interface ButtonProps {
  title: string;
  onPress: () => void;
  variant?: "primary" | "secondary" | "outlined" | "ghost" | "danger";
  size?: "small" | "medium" | "large";
  disabled?: boolean;
  loading?: boolean;
  style?: ViewStyle;
  titleStyle?: TextStyle;
  testID?: string;
  icon?: React.ReactNode;
  iconPosition?: "left" | "right";
}

export default function Button({
  title,
  onPress,
  variant = "primary",
  size = "medium",
  disabled = false,
  loading = false,
  style,
  titleStyle,
  testID,
  icon,
  iconPosition = "left",
}: ButtonProps) {
  const localizedStyles = useLocalizedStyles();
  const { width } = useWindowDimensions();

  // Use runtime window dimensions instead of module-level static value
  const isMobileSize = width < 768;

  // Generate dynamic styles based on current screen size
  const styles = useMemo(() => getStyles(localizedStyles, isMobileSize), [localizedStyles, isMobileSize]);

  const isDisabled = disabled || loading;

  const content = (
    <>
      {loading && (
        <ActivityIndicator
          size="small"
          color={variant === "primary" ? COLORS.white : COLORS.primary}
          style={styles.loadingIndicator}
        />
      )}
      {!loading && icon && iconPosition === "left" && <>{icon}</>}
      <Text
        style={[
          styles.title,
          styles[`${variant}Title`],
          styles[`${size}Title`],
          isDisabled && styles.disabledTitle,
          titleStyle,
        ]}
        numberOfLines={1}
      >
        {title}
      </Text>
      {!loading && icon && iconPosition === "right" && <>{icon}</>}
    </>
  );

  return (
    <TouchableOpacity
      style={[
        styles.button,
        styles[variant],
        styles[size],
        isDisabled && styles.disabled,
        style,
      ]}
      onPress={isDisabled ? undefined : onPress}
      disabled={isDisabled}
      activeOpacity={0.8}
      testID={testID}
    >
      {content}
    </TouchableOpacity>
  );
}

function getStyles(localizedStyles: ReturnType<typeof useLocalizedStyles>, isMobileSize: boolean) {
  return StyleSheet.create({
    button: {
      flexDirection: localizedStyles.row as any,
      alignItems: "center",
      justifyContent: "center",
      borderRadius: 12,
      minHeight: 44,
      paddingHorizontal: SPACING.lg,
      gap: SPACING.sm,
    },

    // Variants
    primary: {
      backgroundColor: COLORS.pregnancyPrimary,
      ...createShadowStyle({
        color: COLORS.pregnancyPrimary,
        offset: { width: 0, height: 2 },
        opacity: 0.2,
        radius: 4,
        elevation: 3,
      }),
    },

    secondary: {
      backgroundColor: COLORS.pregnancySecondary,
      ...createShadowStyle({
        color: COLORS.pregnancySecondary,
        offset: { width: 0, height: 2 },
        opacity: 0.2,
        radius: 4,
        elevation: 3,
      }),
    },

    outlined: {
      backgroundColor: "transparent",
      borderWidth: 1.5,
      borderColor: COLORS.pregnancyPrimary,
    },

    ghost: {
      backgroundColor: "transparent",
    },

    danger: {
      backgroundColor: COLORS.error,
      ...createShadowStyle({
        color: COLORS.error,
        offset: { width: 0, height: 2 },
        opacity: 0.2,
        radius: 4,
        elevation: 3,
      }),
    },

    // Sizes
    small: {
      minHeight: isMobileSize ? 28 : 32,
      paddingHorizontal: isMobileSize ? SPACING.xs : SPACING.sm,
      borderRadius: 8,
      paddingVertical: isMobileSize ? 4 : 6,
    },

    medium: {
      minHeight: isMobileSize ? 32 : 36,
      paddingHorizontal: isMobileSize ? SPACING.sm : SPACING.md,
      borderRadius: 10,
      paddingVertical: isMobileSize ? 6 : 8,
    },

    large: {
      minHeight: isMobileSize ? 38 : 44,
      paddingHorizontal: isMobileSize ? SPACING.md : SPACING.lg,
      borderRadius: 12,
      paddingVertical: isMobileSize ? 8 : 10,
    },

    // States
    disabled: {
      opacity: 0.5,
    },

    // Title styles
    title: {
      fontSize: TYPOGRAPHY.base,
      fontWeight: TYPOGRAPHY.button,
      textAlign: "center",
      letterSpacing: 0.2,
    },

    primaryTitle: {
      color: COLORS.white,
    },

    secondaryTitle: {
      color: COLORS.white,
    },

    outlinedTitle: {
      color: COLORS.pregnancyPrimary,
    },

    ghostTitle: {
      color: COLORS.pregnancyPrimary,
    },

    dangerTitle: {
      color: COLORS.white,
    },

    disabledTitle: {
      opacity: 0.7,
    },

    // Size-specific title styles
    smallTitle: {
      fontSize: responsiveFontSize(11),
    },

    mediumTitle: {
      fontSize: responsiveFontSize(13),
    },

    largeTitle: {
      fontSize: responsiveFontSize(15),
    },

    loadingIndicator: {
      marginRight: SPACING.xs,
    },
  });
}

utils/writeQueue.ts.content:
/**
 * Write Queue for AI Operations
 * Separate circuit breaker and retry logic for write/AI operations
 * to ensure they don't get blocked by read circuit breaker states
 */

import { requestWithRetries } from './supabase';

interface WriteOperation<T> {
  id: string;
  operation: () => Promise<T>;
  resolve: (value: T) => void;
  reject: (error: Error) => void;
  retryCount: number;
  createdAt: number;
}

class WriteQueue {
  private queue: WriteOperation<any>[] = [];
  private processing = false;
  private readonly maxRetries = 3;
  private readonly retryDelayMs = 1000;

  async enqueue<T>(operationId: string, operation: () => Promise<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      const writeOp: WriteOperation<T> = {
        id: operationId,
        operation,
        resolve,
        reject,
        retryCount: 0,
        createdAt: Date.now(),
      };

      this.queue.push(writeOp);
      console.log(`📝 Enqueued write operation: ${operationId}`);

      // Start processing if not already running
      this.processQueue();
    });
  }

  private async processQueue(): Promise<void> {
    if (this.processing || this.queue.length === 0) return;

    this.processing = true;
    console.log(`🔄 Processing write queue (${this.queue.length} operations)`);

    while (this.queue.length > 0) {
      const operation = this.queue.shift()!;
      await this.processOperation(operation);
    }

    this.processing = false;
    console.log('✅ Write queue processing completed');
  }

  private async processOperation<T>(op: WriteOperation<T>): Promise<void> {
    try {
      console.log(`🔄 Executing write operation: ${op.id} (attempt ${op.retryCount + 1}/${this.maxRetries + 1})`);

      // Use write-specific circuit breaker with separate key prefix
      const result = await requestWithRetries(
        `write_${op.id}`,
        op.operation,
        2,
        30000
      );

      console.log(`✅ Write operation completed: ${op.id}`);
      op.resolve(result);
    } catch (error) {
      op.retryCount++;

      const errorInfo = {
        operationId: op.id,
        attempt: op.retryCount,
        maxRetries: this.maxRetries,
        error: error instanceof Error ? error.message : String(error),
        ageMs: Date.now() - op.createdAt,
      };

      console.log(`❌ Write operation failed: ${op.id}`, errorInfo);

      if (op.retryCount <= this.maxRetries) {
        // Exponential backoff with jitter
        const delay = this.retryDelayMs * Math.pow(2, op.retryCount - 1) + Math.random() * 1000;
        console.log(`⏳ Retrying write operation ${op.id} in ${Math.round(delay)}ms`);

        setTimeout(() => {
          this.queue.unshift(op); // Put back at front of queue
          this.processQueue();
        }, delay);
      } else {
        console.error(`❌ Write operation exhausted retries: ${op.id}`);
        op.reject(error instanceof Error ? error : new Error(String(error)));
      }
    }
  }

  // Debug helpers
  getQueueStatus() {
    return {
      queueLength: this.queue.length,
      processing: this.processing,
      operations: this.queue.map(op => ({
        id: op.id,
        retryCount: op.retryCount,
        ageMs: Date.now() - op.createdAt,
      })),
    };
  }

  clearQueue() {
    const cleared = this.queue.length;
    this.queue.forEach(op => op.reject(new Error('Queue cleared')));
    this.queue = [];
    console.log(`🗑️ Cleared ${cleared} write operations from queue`);
  }
}

// Global write queue instance
export const writeQueue = new WriteQueue();

// Convenience wrapper for AI operations
export const executeAIOperation = async <T>(
  operationId: string,
  operation: () => Promise<T>
): Promise<T> => {
  return writeQueue.enqueue(`ai_${operationId}`, operation);
};

// Convenience wrapper for database writes
export const executeDatabaseWrite = async <T>(
  operationId: string,
  operation: () => Promise<T>
): Promise<T> => {
  return writeQueue.enqueue(`db_${operationId}`, operation);
};

// Debug helpers for development
if (typeof window !== 'undefined') {
  (window as any).writeQueueStatus = () => writeQueue.getQueueStatus();
  (window as any).clearWriteQueue = () => writeQueue.clearQueue();
}

