import React from 'react';
import { View, StyleSheet, useWindowDimensions, Platform } from 'react-native';
import { FileText, CheckCircle } from 'lucide-react-native';
import Animated, { 
  FadeInRight,
  useAnimatedStyle,
  withRepeat,
  withTiming,
  useSharedValue,
  withDelay,
} from 'react-native-reanimated';
import { COLORS } from '@/utils/modernStyles';
import { scale } from '@/utils/responsive';
import OnboardingPage from '../components/OnboardingPage';
import { t } from '@/utils/i18n';

export default function LabResultsScreen() {
  const translateY = useSharedValue(0);
  const { width } = useWindowDimensions();

  const isDesktop = width >= 768;

  const docWidth = isDesktop ? Math.min(320, width * 0.28) : Math.min(scale(200), width * 0.5);
  const iconSize = isDesktop 
    ? Math.min(160, width * 0.16)
    : Math.min(scale(100), width * 0.25);
  const circleSize = isDesktop 
    ? Math.min(350, width * 0.3)
    : Math.min(scale(280), width * 0.7);
  const checkSize = isDesktop ? 85 : Math.min(scale(65), width * 0.16);

  React.useEffect(() => {
    translateY.value = withDelay(
      300,
      withRepeat(
        withTiming(-12, { duration: 1800 }),
        -1,
        true
      )
    );
  }, []);

  const floatingStyle = useAnimatedStyle(() => ({
    transform: [{ translateY: translateY.value }],
  }));

  const pageTitle = t('onboardingLabsTitle');
  const pageSubtitle = t('onboardingLabsSubtitle');
  const pageDescription = t('onboardingLabsDescription');

  console.log('[LAB_RESULTS_SCREEN] Rendering with:', {
    title: pageTitle,
    subtitle: pageSubtitle,
    description: pageDescription,
  });

  return (
    <OnboardingPage
      title={pageTitle}
      subtitle={pageSubtitle}
      description={pageDescription}
      illustration={
        <View style={styles.container}>
          <Animated.View style={[styles.documentWrapper, floatingStyle]}>
            <View style={[styles.document, { width: docWidth, height: docWidth * 1.3 }]}>
              <FileText size={iconSize} color={COLORS.info} strokeWidth={2.5} />

              <View style={styles.contentLines}>
                <View style={styles.line1} />
                <View style={styles.line2} />
                <View style={styles.line3} />
                <View style={styles.line4} />
              </View>
            </View>
          </Animated.View>

          <Animated.View 
            entering={Platform.OS !== 'web' ? FadeInRight.delay(1000).duration(800).springify() : undefined}
            style={styles.checkmark}
          >
            <View style={styles.checkmarkBg}>
              <CheckCircle 
                size={checkSize} 
                color={COLORS.success} 
                fill={COLORS.white} 
                strokeWidth={3} 
              />
            </View>
          </Animated.View>

          <View style={[styles.decorBox, styles.decorBox1, { width: isDesktop ? 55 : scale(70), height: isDesktop ? 55 : scale(70) }]} />
          <View style={[styles.decorBox, styles.decorBox2, { width: isDesktop ? 40 : scale(50), height: isDesktop ? 40 : scale(50) }]} />
        </View>
      }
      gradientColors={[COLORS.white, COLORS.infoLight]}
    />
  );
}

const styles = StyleSheet.create({
  container: {
    width: '100%',
    height: '100%',
    justifyContent: 'center',
    alignItems: 'center',
    position: 'relative',
  },
  documentWrapper: {
    position: 'relative',
  },
  document: {
    backgroundColor: COLORS.white,
    borderRadius: 24,
    padding: scale(32),
