utils/connectionHealth.ts.content:
import { supabase } from './supabase';

export interface ConnectionHealthStatus {
  isHealthy: boolean;
  latency: number;
  error?: string;
  timestamp: number;
}

let lastHealthCheck: ConnectionHealthStatus | null = null;
let healthCheckPromise: Promise<ConnectionHealthStatus> | null = null;

export const checkConnectionHealth =
  async (): Promise<ConnectionHealthStatus> => {
    // True single-flight pattern - reuse existing promise if in progress
    if (healthCheckPromise) {
      console.log('🔄 Health check already in progress, reusing existing promise');
      return healthCheckPromise;
    }

    // Create the promise and store it for single-flight
    healthCheckPromise = performHealthCheck();

    try {
      const result = await healthCheckPromise;
      return result;
    } finally {
      // Clear the promise once done
      healthCheckPromise = null;
    }
  };

const performHealthCheck = async (): Promise<ConnectionHealthStatus> => {
    const startTime = Date.now();

    try {
      // Simplified health check - just test basic connectivity
      const traceId = `health_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
      console.log(`🏥 Health check starting [${traceId}]`);

      // Simple ping test with shorter timeout
      const { data, error } = await Promise.race([
        supabase.from('profiles').select('count').limit(1).maybeSingle(),
        new Promise<never>((_, reject) =>
          setTimeout(() => reject(new Error("Health check timeout after 2s")), 2000),
        ),
      ]);

      const latency = Date.now() - startTime;
      const structuredLog = {
        traceId,
        latency,
        isHealthy: !error && latency <= 2000,
        errorCode: error?.code,
        timestamp: Date.now()
      };

      if (error || latency > 2000) {
        lastHealthCheck = {
          isHealthy: false,
          latency,
          error: error?.message || `High latency: ${latency}ms > 2000ms threshold`,
          timestamp: Date.now(),
        };
        console.log(`⚠️ Health check failed [${traceId}]:`, structuredLog);
      } else {
        lastHealthCheck = {
          isHealthy: true,
          latency,
          timestamp: Date.now(),
        };
        console.log(`✅ Health check passed [${traceId}]:`, structuredLog);
      }

      console.log("🏥 Connection health check:", lastHealthCheck);
      return lastHealthCheck;
    } catch (error) {
      const latency = Date.now() - startTime;
      lastHealthCheck = {
        isHealthy: false,
        latency,
        error: error instanceof Error ? error.message : "Unknown error",
        timestamp: Date.now(),
      };

      console.warn("⚠️ Connection health check failed:", lastHealthCheck);
      return lastHealthCheck;
    }
  };

export const getLastHealthCheck = (): ConnectionHealthStatus | null => {
  return lastHealthCheck;
};

// Cache health status for 30 seconds
export const getCachedHealthStatus = (): ConnectionHealthStatus | null => {
  if (!lastHealthCheck) return null;

  const age = Date.now() - lastHealthCheck.timestamp;
  if (age > 30000) return null; // 30 seconds

  return lastHealthCheck;
};

components/PregnancyWeeksDisplay.tsx.content:
import React, { useState } from 'react';
import { View, Text, StyleSheet, ScrollView, Platform, ViewStyle, StyleProp } from 'react-native';
import { pregnancyWeeksData, WeeklyContent } from '@/data/pregnancyWeeks';
import { t } from '@/utils/i18n';
import { useIsRTL } from '@/utils/useIsRTL';
import AnimatedCard from '@/components/ui/AnimatedCard';
import Section from '@/components/ui/Section';
import Icon from 'react-native-vector-icons/MaterialIcons';

interface PregnancyWeeksDisplayProps {
  currentWeek: number;
  language?: 'en' | 'ar';
}

export default function PregnancyWeeksDisplay({
  currentWeek,
  language = 'en',
}: PregnancyWeeksDisplayProps) {
  const isRTL = useIsRTL();
  const [expandedWeek, setExpandedWeek] = useState<number | null>(currentWeek);

  // Get the current week's data
  const currentWeekData = pregnancyWeeksData.find((w) => w.week === currentWeek);

  // Get updates to display (current week ± 2 weeks)
  const getDisplayedWeeks = (): WeeklyContent[] => {
    const start = Math.max(1, currentWeek - 2);
    const end = Math.min(40, currentWeek + 2);
    return pregnancyWeeksData
      .filter((w) => w.week >= start && w.week <= end)
      .sort((a, b) => b.week - a.week); // Show newest first
  };

  const displayedWeeks = getDisplayedWeeks();

  if (!currentWeekData) {
    return (
      <Section title={language === 'ar' ? 'تحديثات الحمل' : 'Pregnancy Updates'} variant="card">
        <Text style={styles.noDataText}>
          {language === 'ar'
            ? 'لا توجد بيانات متاحة لهذا الأسبوع'
            : 'No data available for this week'}
        </Text>
      </Section>
    );
  }

  const toggleWeek = (week: number) => {
    setExpandedWeek(expandedWeek === week ? null : week);
  };

  const renderWeekCard = (weekData: WeeklyContent, index: number) => {
    const isExpanded = expandedWeek === weekData.week;
    const isCurrent = weekData.week === currentWeek;
    const lang = language;

    return (
      <View
        key={weekData.week}
        style={isCurrent ? [styles.weekCard, styles.currentWeekCard] : styles.weekCard}
      >
        <AnimatedCard
          delay={150 + index * 50}
          onPress={() => toggleWeek(weekData.week)}
          pressable={true}
        >
        <View style={[styles.weekHeader, isRTL && styles.weekHeaderRTL]}>
          <View style={[styles.weekBadge, isCurrent && styles.currentWeekBadge]}>
            <Text style={[styles.weekNumber, isCurrent && styles.currentWeekNumber]}>
              {lang === 'ar' ? `الأسبوع ${weekData.week}` : `Week ${weekData.week}`}
            </Text>
          </View>
          <Icon
            name={isExpanded ? 'expand-less' : 'expand-more'}
            size={24}
            color={isCurrent ? '#E91E63' : '#666'}
          />
        </View>

        {isCurrent && (
          <View style={styles.currentBadge}>
            <Icon name="star" size={16} color="#E91E63" />
            <Text style={styles.currentBadgeText}>
              {lang === 'ar' ? 'الأسبوع الحالي' : 'Current Week'}
            </Text>
          </View>
        )}

        {isExpanded && (
          <View style={styles.weekContent}>
            <View style={styles.contentSection}>
              <View style={[styles.sectionHeader, isRTL && styles.sectionHeaderRTL]}>
                <Icon name="child-care" size={20} color="#E91E63" />
                <Text style={[styles.sectionTitle, isRTL && styles.sectionTitleRTL]}>
                  {lang === 'ar' ? 'تطور الجنين' : 'Fetal Development'}
                </Text>
              </View>
              <Text style={[styles.contentText, isRTL && styles.contentTextRTL]}>
                {weekData.fetalDevelopment[lang]}
              </Text>
            </View>

            <View style={styles.contentSection}>
              <View style={[styles.sectionHeader, isRTL && styles.sectionHeaderRTL]}>
                <Icon name="favorite" size={20} color="#E91E63" />
                <Text style={[styles.sectionTitle, isRTL && styles.sectionTitleRTL]}>
                  {lang === 'ar' ? 'التغيرات الأمومية' : 'Maternal Changes'}
                </Text>
              </View>
              <Text style={[styles.contentText, isRTL && styles.contentTextRTL]}>
                {weekData.maternalChanges[lang]}
              </Text>
            </View>

            <View style={styles.contentSection}>
              <View style={[styles.sectionHeader, isRTL && styles.sectionHeaderRTL]}>
                <Icon name="local-hospital" size={20} color="#E91E63" />
                <Text style={[styles.sectionTitle, isRTL && styles.sectionTitleRTL]}>
                  {lang === 'ar' ? 'نصائح صحية' : 'Health Tips'}
                </Text>
              </View>
              <Text style={[styles.contentText, isRTL && styles.contentTextRTL]}>
                {weekData.healthTips[lang]}
              </Text>
            </View>

            <View style={styles.contentSection}>
              <View style={[styles.sectionHeader, isRTL && styles.sectionHeaderRTL]}>
                <Icon name="restaurant" size={20} color="#E91E63" />
                <Text style={[styles.sectionTitle, isRTL && styles.sectionTitleRTL]}>
