  buttonPrimary: {
    backgroundColor: COLORS.primary,
  },

  buttonSecondary: {
    backgroundColor: 'transparent',
    borderWidth: 1,
    borderColor: COLORS.border,
  },

  // Input styles
  input: {
    borderWidth: 1,
    borderColor: COLORS.border,
    borderRadius: BORDER_RADIUS.md,
    paddingVertical: SPACING.md,
    paddingHorizontal: SPACING.lg,
    fontSize: TYPOGRAPHY.base,
    color: COLORS.textPrimary,
    minHeight: 44,
  },

  inputFocused: {
    borderColor: COLORS.primary,
    ...SHADOWS.sm,
  },

  // Text styles
  heading1: {
    fontSize: TYPOGRAPHY['3xl'],
    fontWeight: TYPOGRAPHY.bold,
    color: COLORS.textPrimary,
    lineHeight: TYPOGRAPHY['3xl'] * TYPOGRAPHY.tight,
  } as TextStyle,

  heading2: {
    fontSize: TYPOGRAPHY['2xl'],
    fontWeight: TYPOGRAPHY.semibold,
    color: COLORS.textPrimary,
    lineHeight: TYPOGRAPHY['2xl'] * TYPOGRAPHY.tight,
  } as TextStyle,

  heading3: {
    fontSize: TYPOGRAPHY.xl,
    fontWeight: TYPOGRAPHY.medium,
    color: COLORS.textPrimary,
    lineHeight: TYPOGRAPHY.xl * TYPOGRAPHY.lineHeightNormal,
  } as TextStyle,

  body: {
    fontSize: TYPOGRAPHY.base,
    fontWeight: TYPOGRAPHY.normal,
    color: COLORS.textPrimary,
    lineHeight: TYPOGRAPHY.base * TYPOGRAPHY.lineHeightNormal,
  } as TextStyle,

  caption: {
    fontSize: TYPOGRAPHY.sm,
    fontWeight: TYPOGRAPHY.normal,
    color: COLORS.textSecondary,
    lineHeight: TYPOGRAPHY.sm * TYPOGRAPHY.lineHeightNormal,
  } as TextStyle,

  // Layout styles - React Native native
  container: {
    flex: 1,
    width: '100%',
    height: '100%',
    backgroundColor: COLORS.background,
  },

  fullScreenContainer: {
    flex: 1,
    width: screenWidth,
    height: screenHeight,
    backgroundColor: COLORS.background,
